import{z as o,x as i,o as E,c as A,q as s,j as t,D as e,d as B,s as n,S as d}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"流水线寄存器","description":"","frontmatter":{"title":"流水线寄存器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pipeline-registers.md","filePath":"cs/pipeline-registers.md","lastUpdated":1791413859000}'),l={name:"cs/pipeline-registers.md"};function p(D,a,c,C,_,m){const r=i("Mermaid");return E(),A("div",null,[a[2]||(a[2]=s('<h1 id="流水线寄存器" tabindex="-1">流水线寄存器 <a class="header-anchor" href="#流水线寄存器" aria-label="Permalink to &quot;流水线寄存器&quot;">​</a></h1><div class="epigraph"><p>相邻两级之间必须有锁存：本拍算完的 PC、指令字和控制位，下一拍才能被下一级当成稳定输入。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/pipeline-five-stage">上一课</a>把通路切成 IF/ID/EX/MEM/WB，并已经点名「级间要插寄存器」。本课不重画五级，也不从组合数据通路另起。缺口是：重叠若没有隔离，后一级的组合逻辑会直接搅进前一级尚未稳定的网。本课只钉流水线寄存器里该锁什么，以及控制信号如何随指令向后走。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五级在纸上是五段组合云。同一拍里 IF 正在取下一条，EX 正在用上一条的操作数；若 ALU 输入直接连寄存器堆读口，堆的地址已经换成新指令的 <code>rs</code>，旧指令的运算被破坏。缺口不是再加一级，而是<strong>每级边界上的锁存：只让本级在时钟沿把产出交给下级，级内组合在一拍内算完</strong>。</p><p>控制同样要走寄存器。上一课假定真值表在一拍里驱动整条通路；重叠之后，MEM 的 <code>MemWrite</code> 必须属于正在访存的那条指令，而不能属于刚在 ID 译出的那条。</p><p><span class="marginnote">教学机常画 IF/ID、ID/EX、EX/MEM、MEM/WB 四组。WB 写堆发生在时钟沿，通常不再需要第五组「WB 之后」。</span></p><p><span class="marginnote">可以把它想象成流水线上的托盘：每道工序做完，把半成品连同工单（控制位、<code>rd</code>）一起放上托盘，传给下一道工序。没有托盘，两道工序就共用同一张工作台，后一道会在前一道还没完工时乱动对方的东西。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IF/ID 锁 PC+4 与指令字。ID/EX 锁两个操作数、立即数、目的寄存器号，以及 EX/MEM/WB 要用的控制位。EX/MEM 锁 ALU 结果、要写的数据、分支条件。MEM/WB 锁从存储器或 ALU 来的写回值与目的号。</p>',10)),(E(),t(d,null,{default:e(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20IF%5B%22IF%20%E7%BB%84%E5%90%88%22%5D%20--%3E%20R1%5B%22IF%2FID%20%E9%94%81%E5%AD%98%22%5D%0A%20%20R1%20--%3E%20ID%5B%22ID%20%E7%BB%84%E5%90%88%22%5D%0A%20%20ID%20--%3E%20R2%5B%22ID%2FEX%20%E9%94%81%E5%AD%98%22%5D%0A%20%20R2%20--%3E%20EX%5B%22EX%20%E7%BB%84%E5%90%88%22%5D%0A%20%20EX%20--%3E%20R3%5B%22EX%2FMEM%20%E9%94%81%E5%AD%98%22%5D%0A%20%20R3%20--%3E%20MEM%5B%22MEM%20%E7%BB%84%E5%90%88%22%5D%0A%20%20MEM%20--%3E%20R4%5B%22MEM%2FWB%20%E9%94%81%E5%AD%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<p>停顿与冲刷后课才引入：本课假定每拍四组都装新值。气泡在后课里就是把某组控制位置成「不写、不访存」的 NOP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>锁存把「同时在飞的几条指令」变成几份互不干扰的快照。程序员仍看见顺序 ISA：写回值来自 MEM/WB，与 IF 正在取的那条无关。时钟周期覆盖最慢一级的组合延迟<strong>加上</strong>寄存器建立时间；上一课说的「时钟收到最慢一段」在本课才有对象。</p><p><span class="marginnote">数字实例：设最慢一级组合延迟 200 ps、寄存器建立时间 50 ps，则时钟周期必须不短于 250 ps。少算建立时间这一份，时钟沿到来时锁存器可能锁进还没稳定的值，流水线随机出错且极难复现。</span></p><p>目的寄存器号必须随指令走完 WB。否则写回时堆地址会用错成更年轻指令的 <code>rd</code>。这不是数据冒险——值可以是对的——而是控制与标识没有随流水线前进。</p><p>「<code>rd</code> 必须随身携带」如果违反，会坏在哪一步？</p>',6)),(E(),t(d,null,{default:e(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E6%8B%8D%201%EF%BC%9Aadd%20%E5%9C%A8%20ID%EF%BC%8Crd%3Dx5%20%E9%94%81%E8%BF%9B%20ID%2FEX%22%5D%20--%3E%20T2%5B%22%E6%8B%8D%202%EF%BC%9Aadd%20%E8%BF%9B%20EX%EF%BC%8Csub%20%E5%9C%A8%20ID%20%E8%AF%91%E5%87%BA%20x6%22%5D%0A%20%20T2%20--%3E%20BAD%5B%22%E5%9D%8F%E8%AE%BE%E8%AE%A1%EF%BC%9Aadd%20%E7%9A%84%20rd%20%E8%A2%AB%20sub%20%E7%9A%84%20x6%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20T2%20--%3E%20GOOD%5B%22%E6%AD%A3%E7%A1%AE%E5%81%9A%E6%B3%95%EF%BC%9Aadd%20%E6%90%BA%E5%B8%A6%E8%87%AA%E5%B7%B1%E7%9A%84%20x5%20%E5%89%AF%E6%9C%AC%E5%89%8D%E8%BF%9B%22%5D%0A%20%20BAD%20--%3E%20T3%5B%22%E6%8B%8D%204%EF%BC%9Aadd%20%E5%9C%A8%20WB%EF%BC%8C%E5%A0%86%E5%9C%B0%E5%9D%80%E5%8D%B4%E6%8B%BF%E5%88%B0%20x6%22%5D%0A%20%20T3%20--%3E%20BUG%5B%22add%20%E7%9A%84%E7%BB%93%E6%9E%9C%E5%86%99%E8%BF%9B%20x6%EF%BC%8Cx5%20%E6%B0%B8%E8%BF%9C%E6%B2%A1%E8%A2%AB%E6%9B%B4%E6%96%B0%22%5D%0A%20%20GOOD%20--%3E%20T4%5B%22%E6%8B%8D%204%EF%BC%9Aadd%20%E5%86%99%E5%9B%9E%20x5%EF%BC%8C%E4%B8%8E%E7%A8%8B%E5%BA%8F%E9%A2%84%E6%9C%9F%E4%B8%80%E8%87%B4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">这条坏路径最阴险的地方：ALU 算出的值是对的，指令顺序也对，唯独写错了格子。调试时程序逻辑看起来没问题，某个寄存器却莫名变了——根源只是 5 位的目的寄存器号没有跟着指令走完四拍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不检测相关，不插入气泡，不冲刷。结构上两级抢同一端口，是<a href="/cs/structural-hazard">结构冒险</a>的缺口。也不把流水线寄存器当成 ISA 可见状态：调试器看见的是提交后的架构寄存器。</p><p>后课默认：谈到经典五级，级间有四组锁存，控制位随指令前进。理想情况下每拍各组前进一格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重叠靠级间锁存隔离组合网；没有它们，后级会改写前级的输入。</li><li>操作数、PC、<code>rd</code> 和控制位都要随指令走完该走的级。</li><li>结构冲突与 RAW 转发都是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V 流水线数据通路；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',6))])}const I=o(l,[["render",p]]);export{h as __pageData,I as default};
